import { Paragraph, Heading, CodeBlock } from "../components";

export default function GlobalScriptsPage() {
    return [
        Paragraph("Global scripts are plain files in `~/.x.sh/scripts/`. Each script is executed with the program stored in its metadata (or the global default from `x --config`)."),
        Heading(3, "Creating and editing"),
        Paragraph("`x -i` is the primary workflow. x opens your `$EDITOR`, and on save, writes the file and metadata. &lt;br&gt; Re-running `x -i &lt;name&gt;` on an existing script lets you edit in place or rename."),
        Heading(3, "Passing arguments"),
        CodeBlock(`# Script: curl-google (bash)
curl -s "https://google.com$1"

$ x curl-google /search
# → curl -s "https://google.com/search"`),
        Heading(3, "Program / interpreter"),
        Paragraph("The `program` field in metadata determines how x invokes the file — `bash`, `python`, `node`, `go run`, etc. Set per-script during `x -i` or rely on the global default."),
        Heading(3, "Groups"),
        Paragraph("Metadata `groups` are free-form tags for organization. They appear in `x --ls` output to help you scan large script collections."),
        Heading(3, "Symlinks vs scripts"),
        Paragraph("`x --ln` creates a symlink in `~/.local/bin/`, not a copy. The symlink points at the script file in `~/.x.sh/scripts/`, so edits via `x -i` are reflected immediately."),
    ];
}
