import { Paragraph, Heading, CodeBlock, Callout, BulletList } from "../components";

export default function ProjectLocalPage() {
    return [
        Paragraph("Place a file named `x.yml` in your **current working directory**. When you run `x &lt;name&gt;`, x loads it and looks for a top-level key matching `&lt;name&gt;`. If found, the entry runs; otherwise x falls back to global scripts."),
        Callout("warn", "Only the CWD is checked for `x.yml` — not parent directories. Invalid YAML fails immediately; x does not fall back to global scripts on parse errors."),
        Heading(3, "String entries (inline scripts)"),
        CodeBlock(`lint: npm run lint

build: |
  VERSION="$1"
  npm run build
  npm version "$VERSION"
  git push --tags`, "x.yml"),
        Paragraph("Extra CLI arguments after the command name become `$1`, `$2`, … in the script body."),
        Heading(3, "Mapping entries (nested subcommands)"),
        CodeBlock(`deploy:
  $: |
    echo "Deploying (default)"
    x deploy dev
  dev: npm run deploy:dev
  prod: npm run deploy:prod
  test:
    unit: npx jest unit
    integration: npx jest integration`, "Nested commands"),
        BulletList([
            "`$` — default handler when you run the parent with no further arguments (`x deploy`).",
            "Any other key — nested subcommand; mappings can nest arbitrarily deep.",
            "`x deploy prod` → `deploy.prod`",
            "`x deploy test unit` → `deploy.test.unit`",
        ]),
        Callout("info", "If a mapping has nested keys but no `$` handler, invoking the parent alone (e.g. `x deploy`) produces an error asking you to add `$` or pass a subcommand."),
        Heading(3, "Execution details"),
        Paragraph("Local scripts use your configured **default program** (`x --config` → `default_program` in `~/.x.sh/config.json`), typically `bash`. No per-entry metadata is supported."),
        Heading(3, "Activity tracking"),
        Paragraph("Runs from `x.yml` are **not** recorded in `x --ls` activity data — only global scripts are tracked."),
    ];
}
