import { Paragraph, Heading, CodeBlock, Callout, BulletList } from "../components";

export default function CommandsPage() {
    return [
        Heading(3, "`x --init [name] [script]` / `x -i`"),
        Paragraph("Create a new global script or re-open an existing one in your editor."),
        BulletList([
            "`x -i` — fully interactive (name, description, language, editor).",
            "`x -i my-script` — prompts for metadata, opens editor. If the script exists, you can rename it first; metadata and history follow the new name.",
            "`x -i my-script \"echo hello\"` — creates the script with inline content using the default or existing program.",
        ]),
        Callout("info", "Script names must be non-empty and contain only letters, numbers, and dashes."),
        Heading(3, "`x &lt;script_name&gt; [args…]`"),
        Paragraph("Execute a command using the resolution order described in Architecture. Arguments are forwarded verbatim."),
        Heading(3, "`x --ls` / `x -l`"),
        Paragraph("List all global scripts in a table with description, program, groups, and activity timestamps."),
        Heading(3, "`x --delete &lt;name&gt;` / `x -d`"),
        Paragraph("Remove a global script and its metadata. Does **not** remove symlinks created with `x --ln` — delete those separately."),
        Heading(3, "`x --ln &lt;name&gt; [link_name]`"),
        Paragraph("Symlink a script into `~/.local/bin/` so you can invoke it without the `x` prefix."),
        CodeBlock(`x --ln my-script          # → ~/.local/bin/my-script
x --ln my-script alias    # → ~/.local/bin/alias
x -d --ln my-script       # remove the symlink`),
        Heading(3, "`x --src &lt;name&gt;`"),
        Paragraph("Print the absolute path of a script or app file. Resolution: local app → global app → global script. `x.yml` keys are not matched."),
        Heading(3, "`x -i --app [--local | --global] [&lt;name&gt;]`"),
        Paragraph("Create a new app YAML file. Scope flags control where the file is written; without them, x prompts interactively."),
        Heading(3, "`x --config`"),
        Paragraph("Interactive configuration for default script language and LLM provider. See the Configuration section."),
        Heading(3, "`x --ai` and `x -i --ai [name]`"),
        Paragraph("LLM-powered command and script generation. Requires `~/.x.sh/config/llm.sh`. See AI Integration."),
    ];
}
