import { Paragraph, Heading, CodeBlock } from "../components";

export default function QuickstartPage() {
    return [
        Heading(3, "1. Create your first script"),
        CodeBlock(`x --init hello-world
# or: x -i hello-world`),
        Paragraph("Interactive prompts ask for the script name (alphanumeric + dashes), an optional description, and a programming language. Your `$EDITOR` opens so you can write the script body."),
        Heading(3, "2. Run it"),
        CodeBlock(`x hello-world
x hello-world arg1 arg2   # args pass through to the script`),
        Heading(3, "3. List installed scripts"),
        CodeBlock(`x --ls
# or: x -l`),
        Paragraph("Shows a formatted table with name, description, language, groups, and last-run timestamps."),
        Heading(3, "4. Add to PATH (optional)"),
        CodeBlock(`x --ln hello-world
# Now run directly: hello-world`),
        Heading(3, "5. Project-local commands (optional)"),
        Paragraph("Drop an `x.yml` in your project root to define repo-specific tasks:"),
        CodeBlock(`test: npm test
build: |
  npm run build
  echo "Built $1"   # $1 = first arg after 'build'`, "x.yml"),
        CodeBlock(`x test
x build v1.0.0`),
    ];
}
