import { Paragraph, Heading, DocLink } from "../components";

export default function FaqPage() {
    return [
        Heading(3, "Why does `x my-script` not find my `x.yml` entry?"),
        Paragraph("`x.yml` is only read from the **current working directory**, not parent directories. `cd` to the directory containing `x.yml`, or use a global script / app instead."),
        Heading(3, "Why does a local app work from a subdirectory but `x.yml` does not?"),
        Paragraph("By design. Apps walk up the directory tree; `x.yml` does not. Put shared project commands in a root-level app or keep `x.yml` usage to single-directory workflows."),
        Heading(3, "`x --ln` created a symlink but the command is not found"),
        Paragraph("Ensure `~/.local/bin` is on your `PATH`. Run `echo $PATH` and verify. You may need to open a new shell after updating your rc file."),
        Heading(3, "My app fails validation after editing"),
        Paragraph("Run `x -i --app --local &lt;name&gt;` (or `--global`) to re-enter the edit/revert loop. Common issues: missing handler for a leaf command, invalid synopsis syntax, or both `$` and `$.import` present."),
        Heading(3, "Can I use extensions in script names?"),
        Paragraph("Script **names** you pass to `x` are extensionless (e.g. `x c-test`). The file on disk can include an extension (`c-test.c`); x resolves by basename match."),
        Heading(3, "Does `x --delete` remove symlinks?"),
        Paragraph("No. Use `x -d --ln &lt;name&gt;` to remove symlinks separately."),
        Heading(3, "Where is the source code?"),
        DocLink("https://github.com/michaelmunson/x.sh", "github.com/michaelmunson/x.sh", true),
    ];
}
