import { Paragraph, Heading, CodeBlock, Callout, BulletList } from "../components";

export default function OverviewPage() {
    return [
        Paragraph("**x** is a Rust-powered CLI that helps you create, organize, and run scripts across projects. Think of it as a script registry with metadata, editor integration, and optional symlinks into your PATH — plus two YAML-based layers for project commands and full multi-command apps."),
        Heading(3, "What makes x different"),
        BulletList([
            "**Global scripts** live in `~/.x.sh/scripts/` with per-script metadata (description, language, groups) and usage tracking.",
            "**Project-local commands** in `./x.yml` let you version-control task runners alongside your repo — no install step required for teammates.",
            "**Apps** (`&lt;name&gt;.x.yml`) turn YAML into validated CLIs with options, arguments, nested subcommands, and bash handlers — before any bash runs, x parses and validates the user's input.",
            "**AI helpers** (`x --ai`, `x -i --ai`) generate shell commands and scripts when you configure an LLM provider.",
        ]),
        Heading(3, "Three ways to run a command"),
        CodeBlock(`1. ./x.yml          → project-local inline script (CWD only)
2. ./&lt;name&gt;.x.yml    → local app (CWD, then parent dirs)
3. ~/.x.sh/apps/     → global app
4. ~/.x.sh/scripts/  → installed global script`, "Resolution order when you run `x &lt;name&gt; …`"),
        Callout("tip", "Use `x --src &lt;name&gt;` to print the absolute path of a script or app file without executing it — handy for piping into editors or CI."),
    ];
}
