import { Paragraph, Heading, CodeBlock, Callout, BulletList, OrderedList } from "../components";

export default function InstallationPage() {
    return [
        Heading(3, "Automated install (recommended)"),
        Paragraph("The install script clones the repo, builds in release mode, and places the binary in `~/.local/bin/`."),
        CodeBlock(`curl -fsSL https://raw.githubusercontent.com/michaelmunson/x.sh/main/install.sh | bash`, "One-liner"),
        Paragraph("Or download and run manually:"),
        CodeBlock(`wget https://raw.githubusercontent.com/michaelmunson/x.sh/main/install.sh
bash install.sh`),
        Heading(4, "Requirements"),
        BulletList([
            "**Rust / Cargo** — the script prompts you to install via rustup if missing.",
            "**Git** — used to clone the repository (skipped if you run the script from inside the repo).",
            "An internet connection for the initial clone and build.",
        ]),
        Heading(4, "What the script does"),
        OrderedList([
            "Checks for Rust/Cargo.",
            "Clones `github.com/michaelmunson/x.sh` (or uses the current directory if already in the repo).",
            "Runs `cargo build --release`.",
            "Copies `target/release/x` to `~/.local/bin/x`.",
            "Verifies the installation by running `x --help`.",
        ]),
        Callout("warn", "Ensure `~/.local/bin` is on your PATH. Add `export PATH=\"$HOME/.local/bin:$PATH\"` to `~/.bashrc`, `~/.zshrc`, or `~/.profile`, then restart your shell.", "PATH"),
        Heading(3, "Manual build"),
        CodeBlock(`git clone https://github.com/michaelmunson/x.sh.git
cd x.sh
cargo build --release
# Binary at target/release/x — copy or symlink into your PATH`),
        Heading(3, "First-run directory layout"),
        Paragraph("On first use, x creates `~/.x.sh/` with the following structure:"),
        CodeBlock(`~/.x.sh/
├── scripts/          # your global script files
├── apps/             # global app YAML files (&lt;name&gt;.x.yml)
├── metadata/         # per-script TOML metadata
│   └── &lt;name&gt;.toml
├── config.json       # default_program and other settings
├── metadata.json     # usage / activity tracking
└── config/
    └── llm.sh        # LLM provider script (after x --config)`, "~/.x.sh/"),
    ];
}
