import { Paragraph, Heading, CodeBlock, ResolutionPipeline } from "../components";

export default function ArchitecturePage() {
    return [
        Heading(3, "Command resolution flow"),
        Paragraph("When you invoke `x &lt;name&gt; [args…]`, x walks a fixed resolution chain. The first match wins and the process exits after execution."),
        ResolutionPipeline(),
        Heading(3, "Local app discovery"),
        Paragraph("Unlike `x.yml` (current directory only), **local apps** are discovered by walking from the current working directory up through every parent directory. The nearest `&lt;name&gt;.x.yml` wins. This lets monorepos keep a shared app at the repo root while you work in subdirectories."),
        Heading(3, "Global script lookup"),
        Paragraph("Scripts in `~/.x.sh/scripts/` are matched by exact filename first, then by basename without extension — so `x c-test` finds `c-test.c` automatically."),
        Heading(3, "Metadata model"),
        Paragraph("Each global script can have a companion TOML file at `~/.x.sh/metadata/&lt;name&gt;.toml`:"),
        CodeBlock(`description = "Fetch a URL with curl"
groups = ["network", "utils"]
program = "bash"`, "Example metadata"),
        Paragraph("Activity data (created, updated, last_executed) is stored separately in `~/.x.sh/metadata.json` and shown in `x --ls`."),
        Heading(3, "Inline script execution"),
        Paragraph("Project-local `x.yml` entries and certain inline paths run via your configured default program (typically `bash`):"),
        CodeBlock(`&lt;program&gt; -c '&lt;script body&gt;' x &lt;remaining-args…&gt;`),
        Paragraph("Positional parameters in the script body (`$1`, `$2`, …) refer to arguments after the command name."),
    ];
}
