import { Paragraph, Heading, CodeBlock, BulletList } from "../components";

export default function ConfigurationPage() {
    return [
        Heading(3, "`x --config`"),
        Paragraph("Interactive menu with two options:"),
        Heading(4, "Default Script Language"),
        Paragraph("Sets `default_program` in `~/.x.sh/config.json`. Pre-selected during `x -i` and used for `x.yml` inline execution."),
        CodeBlock(`{
  "default_program": "bash"
}`, "config.json"),
        Heading(4, "LLM Provider"),
        Paragraph("Opens your editor with a template script saved to `~/.x.sh/config/llm.sh`. The script must accept the prompt as `$1` and print the completion to stdout."),
        CodeBlock(`#!/bin/bash
PROMPT="$1"
ollama run llama2 "$PROMPT"`, "llm.sh example"),
        Heading(3, "Environment"),
        BulletList([
            "`$EDITOR` — used by `x -i`, `x -i --app`, and LLM config.",
            "`$PATH` — must include `~/.local/bin` for `x --ln` symlinks.",
        ]),
    ];
}
