import { Paragraph, Heading, CodeBlock, DataTable, BulletList } from "../components";

export default function AppFrameworkPage() {
    return [
        Paragraph("Apps turn a single `&lt;name&gt;.x.yml` file into a structured CLI with options, positional arguments, nested subcommands, and bash handlers. Unlike `x.yml` inline scripts, apps get **parse-time validation** — x checks required args, defaults, choice membership, `requires:` chains, and unknown flags before any handler bash executes."),
        Heading(3, "Where apps live"),
        BulletList([
            "**Local:** `./&lt;name&gt;.x.yml` (discovered from CWD up through parents).",
            "**Global:** `~/.x.sh/apps/&lt;name&gt;.x.yml`.",
        ]),
        Heading(3, "Creating an app"),
        CodeBlock(`x -i --app my-app             # prompts for local vs global
x -i --app --local my-app     # ./my-app.x.yml
x -i --app --global my-app    # ~/.x.sh/apps/my-app.x.yml`),
        Paragraph("After the editor closes, x validates the YAML structure, parses every synopsis string, and checks handler coverage. On failure you can **edit** (re-open) or **revert** (restore prior file or delete the new one)."),
        Heading(3, "App vs project-local"),
        DataTable(["Feature", "`x.yml`", "App (`&lt;name&gt;.x.yml`)"], [
            ["Scope", "CWD only", "CWD + parent walk / global"],
            ["CLI parsing", "None (raw args as $1…)", "Full synopsis DSL + validation"],
            ["Options / flags", "No", "Yes"],
            ["Help generation", "No", "Auto `-h` / `--help` per command"],
            ["Handlers", "Inline YAML strings", "Bash in `$:` block or `$.import`"],
            ["Metadata", "None", "name, version, description"],
        ]),
        Heading(3, "Handler imports"),
        Paragraph("Large apps can split handlers into external YAML files via `$.import`. This is mutually exclusive with an inline `$:` block."),
        CodeBlock(`$.import:
  - ./handlers/build.yml
  - ./handlers/deploy.yml`),
    ];
}
