import { Paragraph, Heading, CodeBlock, Callout } from "../components";

export default function AiPage() {
    return [
        Paragraph("x does not bundle an LLM. Instead, you provide a shell script that forwards prompts to any backend — Ollama, OpenAI CLI, a custom API wrapper, etc."),
        Heading(3, "`x --ai`"),
        Paragraph("Prompts for natural-language instructions, generates a shell command, displays it, and optionally executes after confirmation."),
        CodeBlock(`x --ai
# instructions&gt; aws command to list parameters
#
# Generated Command
# aws ssm describe-parameters
# Run command? [y/N]`),
        Heading(3, "`x -i --ai [name]`"),
        Paragraph("Generates a complete script via LLM and saves it through the normal `x -i` workflow (metadata + file)."),
        Callout("info", "Configure your provider first with `x --config` → LLM Provider. Without `~/.x.sh/config/llm.sh`, AI commands will fail."),
    ];
}
